    "carbono": "sq-en-5aa915cdb9bfb76d2ea6c2e7",
    "carga de color": "sq-en-1fb7a04aa8768f02acf4be1c",
    "Casi toda la masa del átomo se concentra en un núcleo muchísimo menor que el tamaño total del átomo.": "sq-en-f011c213fd2c7ced22cee89f",
    "confinamiento": "sq-en-cdd6b7fcfd1a5f88d203ffce",
